def _parse_transition_time(time_str):
    match = re.fullmatch('(?P<sign>[+-])?(?P<h>\\d{1,3})(:(?P<m>\\d{2})(:(?P<s>\\d{2}))?)?', time_str, re.ASCII)
    if match is None:
        raise ValueError(f'Invalid time: {time_str}')
    h, m, s = (int(v or 0) for v in match.group('h', 'm', 's'))
    if h > 167:
        raise ValueError(f'Hour must be in [0, 167]: {time_str}')
    if match.group('sign') == '-':
        h, m, s = (-h, -m, -s)
    return (h, m, s)

def _parse_tz_delta(tz_delta):
    match = re.fullmatch('(?P<sign>[+-])?(?P<h>\\d{1,3})(:(?P<m>\\d{2})(:(?P<s>\\d{2}))?)?', tz_delta, re.ASCII)
    assert match is not None, tz_delta
    h, m, s = (int(v or 0) for v in match.group('h', 'm', 's'))
    total = h * 3600 + m * 60 + s
    if h > 24:
        raise ValueError(f'Offset hours must be in [0, 24]: {tz_delta}')
    if match.group('sign') != '-':
        total = -total
    return total

