def shorten(text: str, limit: int=1000, split: int | None=None, separator: str='...') -> str:
    if limit < 2:
        raise ValueError('limit must be greater than or equal to 2.')
    if split is None:
        split = limit // 2
    split = min(split, len(text) // 2)
    if len(text) > limit:
        text = f'{text[:split]}{separator}{text[-split:]}'
    return text

def repr_shorten(value: Any, limit: int=1000, split: int | None=None, separator: str='...') -> str:
    if limit < 4:
        raise ValueError('limit must be greater than or equal to 4.')
    text = repr(value)
    return shorten(text, limit=limit, split=split, separator=separator)

