import re

def translate(pattern):
    return ''.join(map(replace, separate(pattern)))

def separate(pattern):
    return re.finditer('([^\\[]+)|(?P<set>[\\[].*?[\\]])|([\\[][^\\]]*$)', pattern)

def replace(match):
    return match.group('set') or re.escape(match.group(0)).replace('\\*\\*', '.*').replace('\\*', '[^/]*').replace('\\?', '.')

